delete from public.pruef_einheiten where thema_id = 37;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9851, 37, 'Neues oder aufgestocktes, langfristiges Landesprogramm zur Sanierung von Sportstätten (Land)', 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'gemischt', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'land', null, true, 'blind'),
  (9852, 37, 'Sanierung und Ausbau von Sportstätten allgemein zusagen, fortführen oder für einzelne Anlagen (Land)', 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'gemischt', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'land', null, true, 'blind'),
  (9853, 37, 'Barrierefreie und inklusive Sportstätten fördern und bauen (Land)', 'Verbessert Zugang und Teilhabe, berührt den allgemeinen Sanierungsrückstand aber nur, soweit dabei saniert wird. Umbau und Neubau brauchen Mittel und mehrere Jahre; Wirkung auf die Vereinsfinanzen kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9854, 37, 'Investitionsprogramm für Sanierung und Neubau von Schwimmbädern (Land)', 'Setzt am besonders hohen Rückstand bei Bädern an und kann Schließungen verhindern. Dagegen: sehr hohe Bau- und Betriebskosten, lange Bauzeiten; die Wirkung auf die Teilnahme hängt von Lage und Erreichbarkeit ab.', 'gemischt', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'land', null, true, 'blind'),
  (9855, 37, 'Energetische Sanierung von Sportstätten und Bädern zur Senkung der Betriebskosten (Land)', 'Energetische Sanierung senkt Energie- und Betriebskosten nachweislich deutlich (Pilotbad: über 50 % weniger Heizenergie) und baut Sanierungsbedarf ab. Dagegen: hohe Investitionen, lange Bauzeiten und Schließung während der Arbeiten.', 'belegt', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'land', null, true, 'blind'),
  (9856, 37, 'Zustandserfassung, Sportstätten-Atlas und Sportentwicklungsplanung als Grundlage für Investitionen (Land)', 'Bessere Daten und Planung lenken Mittel gezielter, beseitigen den Rückstand aber nicht ohne zusätzliches Geld. Rasch und günstig umsetzbar; Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9857, 37, 'Typenbau, zentrale Bau-Einheit und schnellere Planungs- und Förderverfahren für Sportstätten (Land)', 'Kann Planung und Bau beschleunigen und verbilligen, wo Verwaltungskapazität der Engpass ist. Ohne zusätzliche Mittel bleibt der Rückstand; Aufbau einer zentralen Einheit dauert, Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9858, 37, 'Vorhandene Sportanlagen besser nutzen: Öffnung von Schulanlagen, Buchungsportale, ganzjährige Nutzung (Land)', 'Schafft mehr Trainingszeiten ohne Neubau und lindert so Folgen knapper Anlagen, setzt am Investitionsrückstand selbst aber nicht an. Günstig umsetzbar; Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9859, 37, 'Kostenlose oder stark vergünstigte Nutzung öffentlicher Sportanlagen durch Vereine (Land)', 'Senkt die Nutzungskosten der Vereine und damit den Druck auf Beiträge. Dagegen: Die Kosten verlagern sich auf Kommunen, deren Sportbetriebe schon Verluste ausgleichen; ohne Ausgleich durch das Land kaum tragfähig. Wenig untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9860, 37, 'Investitions- und Instandhaltungsförderung für von Vereinen genutzte oder eigene Sportanlagen (Land)', 'Geld fließt direkt an Vereine für den Zustand ihrer Anlagen, wo der Problemdruck gestiegen ist; einfache Budgets erleichtern den Abruf. Dagegen: Umfang unbestimmt, Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9861, 37, 'Pauschale Förderung von Vereinen und Sportbünden erhöhen und dynamisieren (Land)', 'Verlässliche, mit den Kosten steigende Pauschalen setzen an der finanziellen Lage der Vereine an und erleichtern bezahlbare Beiträge. Dagegen: dauerhafte Haushaltsbelastung; Wirkung auf Beiträge kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9862, 37, 'Förderung des Landessportbunds und Fördervereinbarung fortführen (Land)', 'Sichert bestehende Strukturen und gibt Planungssicherheit, verbessert die finanzielle Lage der Vereine aber kaum, solange die Mittel nicht steigen. Leicht umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (9863, 37, 'Hauptamtliche Unterstützung für Vereine fördern (Verwaltungskräfte, Ansprechpartner, Beratung) (Land)', 'Setzt am größten Existenzproblem an, der Last auf Ehrenamtlichen. Studien: Vereine mit Hauptamt haben weniger Probleme bei Mitgliedern, aber mehr bei den Finanzen; dauerhafte Finanzierung nötig.', 'gemischt', null, 'land', null, true, 'blind'),
  (9864, 37, 'Unbestimmte Zusage, Vereine und Breitensport finanziell zu fördern (Land)', 'Berührt die finanzielle Lage der Vereine, nennt aber weder Instrument noch Umfang; eine spürbare Verbesserung ist so nicht absehbar.', 'offen', null, 'land', null, true, 'blind'),
  (9865, 37, 'Neues Förderprogramm oder Fonds für Vereine und Ehrenamt (Land)', 'Zusätzliche Mittel für Projekte, Nachwuchs und Strukturen setzen an der Lage der Vereine an. Dagegen: Wirkung hängt von Umfang und Antragsaufwand ab; kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9866, 37, 'Bürokratie für Vereine abbauen: einfachere Förderverfahren, Pauschalen, digitale Anträge, Beratung (Land)', 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9867, 37, 'Vereinsrecht entbürokratisieren: Haftung, Dokumentations- und Datenschutzpflichten (Bund)', 'Der Bund regelt Vereins-, Haftungs- und Gemeinnützigkeitsrecht und kann Ehrenamtliche entlasten. Dagegen: Datenschutz ist EU-rechtlich vorgegeben; Wirkung auf Engagement und Vereinsfinanzen kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (9868, 37, 'Vereine bei der Digitalisierung unterstützen (Land)', 'Kann Verwaltungsarbeit erleichtern und Ehrenamtliche entlasten, berührt die finanzielle Lage aber nur am Rand. Leicht umsetzbar, Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9869, 37, 'Vergütung von Übungsleitungen und Trainern fördern bzw. anheben (Land)', 'Setzt am Mangel an Übungsleitungen an, dem zweitgrößten Existenzproblem der Vereine, und entlastet deren Kasse. Dagegen: Studien zeigen, dass Bezahlung unbezahltes Engagement verdrängen kann; dauerhafte Finanzierung nötig.', 'gemischt', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'land', null, true, 'blind'),
  (9870, 37, 'Aus- und Fortbildung von Übungsleitungen und Ehrenamtlichen fördern (Land)', 'Stärkt Qualifikation und Bindung von Ehrenamtlichen, entlastet die Vereinsfinanzen aber nur wenig. Rasch umsetzbar, Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9871, 37, 'Übungsleiter- und Ehrenamtspauschale erhöhen oder vereinheitlichen (Bund)', 'Steuerfreie Pauschalen entlasten Ehrenamtliche, nicht die Vereinskasse, die Zahlungen aufbringen muss; 2026 bereits erhöht. Ob Geldanreize mehr Engagement bringen, ist umstritten (Verdrängungseffekte).', 'gemischt', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'bund', null, true, 'blind'),
  (9872, 37, 'Auf höhere steuerfreie Übungsleiter- und Ehrenamtspauschale hinwirken (Land)', 'Wirkt wie die Erhöhung im Bund, entlastet aber nicht die Vereinskasse; Steuerrecht ist Bundessache, das Land kann nur über den Bundesrat drängen. Ob Geldanreize Engagement fördern, ist umstritten.', 'gemischt', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'land', null, true, 'blind'),
  (9873, 37, 'Anerkennung des Ehrenamts: Ehrenamtskarte mit Vergünstigungen, Sichtbarkeit, Vereinbarkeit (Land)', 'Würdigt Ehrenamtliche und kann Bindung stärken; Evaluationen zeigen Zufriedenheit, aber keinen belegten Effekt auf die Gewinnung neuer Engagierter. Vergünstigungen wie freier Nahverkehr kosten Geld.', 'offen', null, 'land', null, true, 'blind'),
  (9874, 37, 'GEMA-Gebühren für Vereinsveranstaltungen übernehmen (Land)', 'Entlastet Vereine bei Veranstaltungskosten, für Sportvereine meist ein kleiner Posten; die finanzielle Lage verbessert sich nur am Rand. Mit überschaubarem Geld rasch umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (9875, 37, 'Kooperation von Schulen, Kitas und Sportvereinen fördern (Land)', 'Kann Vereinen Nachwuchs und Einnahmen aus Ganztagsangeboten bringen, berührt ihre Finanzlage aber nur am Rand. Hängt von Übungsleitungen am Nachmittag ab; Wirkung kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9876, 37, 'Bundesförderprogramm zur Sanierung kommunaler Sportstätten und Schwimmbäder (Bund)', 'Setzt direkt am Investitionsrückstand an; der Bund finanziert bereits ein Sanierungsprogramm (2025/26 rund 916 Mio. €). Dagegen: Mittel gemessen am Rückstand klein, Kofinanzierung und Planungskapazität der Kommunen begrenzen den Abruf.', 'gemischt', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'bund', null, true, 'blind'),
  (9877, 37, 'Kommunalfinanzen und allgemeine Investitionsmittel für kommunale Infrastruktur stärken (Bund)', 'Mehr Geld für Kommunen kann auch Sportstätten zugutekommen, ist aber nicht zweckgebunden; Sportanlagen konkurrieren mit vielen anderen Bedarfen. Finanzierung und Ausgestaltung offen.', 'offen', null, 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 37 and id not in (9851, 9852, 9853, 9854, 9855, 9856, 9857, 9858, 9859, 9860, 9861, 9862, 9863, 9864, 9865, 9866, 9867, 9868, 9869, 9870, 9871, 9872, 9873, 9874, 9875, 9876, 9877);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9878, 37, 11, null, 'Ehrenamts- und Übungsleiterpauschale spürbar erhöhen, um ehrenamtlich Tätige steuerlich zu entlasten', '{3703}', 9871, 1, 3, null, 'Steuerfreie Pauschalen entlasten Ehrenamtliche, nicht die Vereinskasse, die Zahlungen aufbringen muss; 2026 bereits erhöht. Ob Geldanreize mehr Engagement bringen, ist umstritten (Verdrängungseffekte).', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=57', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9879, 37, 11, null, 'Mehr Anreize für private Gelder und Spenden an Vereine setzen und den Zugang zu öffentlicher Förderung erleichtern', '{3703}', null, 1, 3, null, 'Spendenanreize und leichterer Zugang zu Förderung können Einnahmen der Vereine erhöhen; ohne Ausgestaltung bleibt der Effekt klein. Steuerliche Regeln liegen beim Bund.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=57', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9880, 37, 11, null, 'Vereinspaket für das Ehrenamt, das Bürokratie, Datenschutz und Haftungsfragen angeht', '{3703}', 9867, 1, 3, null, 'Der Bund regelt Vereins-, Haftungs- und Gemeinnützigkeitsrecht und kann Ehrenamtliche entlasten. Dagegen: Datenschutz ist EU-rechtlich vorgegeben; Wirkung auf Engagement und Vereinsfinanzen kaum untersucht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=57', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9881, 37, 11, null, 'In der kommenden Wahlperiode die Bereitstellung der Sportmilliarde sicherstellen', '{3701}', 9876, 2, 3, null, 'Setzt direkt am Investitionsrückstand an; der Bund finanziert bereits ein Sanierungsprogramm (2025/26 rund 916 Mio. €). Dagegen: Mittel gemessen am Rückstand klein, Kofinanzierung und Planungskapazität der Kommunen begrenzen den Abruf.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=61', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9882, 37, 11, 'BE', 'Das Landesprogramm zur Sanierung von Sportstätten ausbauen und langfristig finanziell absichern.', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=111', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9883, 37, 11, 'BE', 'Verlässliche Sanierungsstrategie, bessere Datengrundlage und schnellere Genehmigungen für mehr Planungssicherheit von Bezirken und Vereinen.', '{3701}', 9856, 1, 3, null, 'Bessere Daten und Planung lenken Mittel gezielter, beseitigen den Rückstand aber nicht ohne zusätzliches Geld. Rasch und günstig umsetzbar; Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=111', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9884, 37, 11, 'BE', 'Sportstätten bei Sanierungen energetisch und klimaverträglich modernisieren und multifunktional nutzbar machen.', '{3701,3702}', 9855, 2, 2, null, 'Energetische Sanierung senkt Energie- und Betriebskosten nachweislich deutlich (Pilotbad: über 50 % weniger Heizenergie) und baut Sanierungsbedarf ab. Dagegen: hohe Investitionen, lange Bauzeiten und Schließung während der Arbeiten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=111', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'belegt', '2026-10-08', false, true, 'blind'),
  (9885, 37, 11, 'BE', 'Rechtssichere Regeln, damit gemeinnützige Sportvereine mit erneuerbaren Energien (Eigenversorgung, Einspeisung) Einnahmen erzielen können, ohne die Gemeinnützigkeit zu verlieren.', '{3703,3702}', null, 1, 1, null, 'Einnahmen und Eigenversorgung aus erneuerbaren Energien können Energiekosten der Vereine senken. Das Gemeinnützigkeitsrecht ist aber Bundesrecht; das Land kann es nicht allein regeln.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=111', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9886, 37, 11, 'BE', 'Schwimmbäder modernisieren: bestehende Bäder energiesparsam sanieren, neue Wasserflächen bei hohem Bedarf schaffen, Betriebsabläufe effizienter machen.', '{3701}', 9855, 2, 2, null, 'Energetische Sanierung senkt Energie- und Betriebskosten nachweislich deutlich (Pilotbad: über 50 % weniger Heizenergie) und baut Sanierungsbedarf ab. Dagegen: hohe Investitionen, lange Bauzeiten und Schließung während der Arbeiten.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=112', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'belegt', '2026-10-08', false, true, 'blind'),
  (9887, 37, 11, 'BE', 'Führung und Struktur des landeseigenen Bäderbetriebs kritisch überprüfen.', '{3702}', null, 1, 3, null, 'Eine Prüfung des Bäderbetriebs kann Effizienzreserven aufzeigen und Verluste mindern, senkt Kosten aber erst durch Folgeschritte. Rasch umsetzbar, Ergebnis offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=112', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9888, 37, 11, 'BE', 'Beim Bund und bei der EU darauf hinwirken, dass das Land stärker von Förderprogrammen für Sportstätten profitiert.', '{3701}', null, 1, 2, null, 'Mehr Bundes- und EU-Mittel würden Sanierungen finanzieren, das Land kann darauf aber nur hinwirken; Erfolg hängt von fremden Entscheidungen ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=112', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9889, 37, 11, 'BE', 'Sportflächen ganzjährig nutzbar machen, etwa mit moderner Beleuchtung, witterungsbeständigen Belägen und besserer Organisation der Trainingszeiten.', '{3701}', 9858, 1, 3, null, 'Schafft mehr Trainingszeiten ohne Neubau und lindert so Folgen knapper Anlagen, setzt am Investitionsrückstand selbst aber nicht an. Günstig umsetzbar; Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=112', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9890, 37, 11, 'BE', 'Bei der Sanierung eines großen Sportparks inklusive und barrierefreie Außensportstätten für umliegende Sportvereine planen.', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=112', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9891, 37, 11, 'BE', 'Sport-AGs an Kitas und Schulen ausbauen, Zusammenarbeit mit Sportvereinen stärken und Hürden für Kooperationen von Schulen und Vereinen abbauen.', '{3703}', 9875, 1, 2, null, 'Kann Vereinen Nachwuchs und Einnahmen aus Ganztagsangeboten bringen, berührt ihre Finanzlage aber nur am Rand. Hängt von Übungsleitungen am Nachmittag ab; Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=113', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9892, 37, 11, 'BE', 'Ehrenamt im Vereinssport stärker anerkennen, Bürokratie abbauen und Förderverfahren vereinfachen.', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=114', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9893, 37, 11, 'BE', 'Hauptamtliche Strukturen ausbauen (Ansprechpartner, Beratung, einfache Förderprogramme), die Vereine und Ehrenamtliche entlasten.', '{3703}', 9863, 2, 2, null, 'Setzt am größten Existenzproblem an, der Last auf Ehrenamtlichen. Studien: Vereine mit Hauptamt haben weniger Probleme bei Mitgliedern, aber mehr bei den Finanzen; dauerhafte Finanzierung nötig.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=114', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9894, 37, 11, 'BE', 'Sportvereine bei Digitalisierung und beim Einsatz Künstlicher Intelligenz unterstützen.', '{3703}', 9868, 1, 3, null, 'Kann Verwaltungsarbeit erleichtern und Ehrenamtliche entlasten, berührt die finanzielle Lage aber nur am Rand. Leicht umsetzbar, Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=115', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9895, 37, 11, 'BE', 'Digitale Zugangs- und Buchungssysteme für Sportanlagen fördern, damit vorhandene Flächen flexibler und länger genutzt werden.', '{3701}', 9858, 1, 3, null, 'Schafft mehr Trainingszeiten ohne Neubau und lindert so Folgen knapper Anlagen, setzt am Investitionsrückstand selbst aber nicht an. Günstig umsetzbar; Wirkung kaum untersucht.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=115', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9896, 37, 11, 'BE', 'Steganlagen von Wassersportvereinen erhalten, Planungssicherheit schaffen und Bürokratie abbauen, damit Vereine ihre Anlagen langfristig betreiben können.', '{3703}', null, 1, 2, null, 'Planungssicherheit und weniger Auflagen sichern den Betrieb von Steganlagen für Wassersportvereine, betreffen aber nur einen kleinen Teil der Vereine.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=115', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9897, 37, 11, 'MV', 'Sport-Pakt mit Kommunen, Verbänden und Vereinen zum Abbau des Sanierungs- und Investitionsstaus bei Sportstätten; Landesmittel für Sportförderung von 13 auf 20 Mio. erhöhen', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=83', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9898, 37, 11, 'MV', 'Digitalen Sportstätten-Atlas zu Zustand, Sanierungsbedarf und Nutzung einrichten; darauf Sportstättenbericht und Sportentwicklungsplanung als Grundlage für Investitionen', '{3701}', 9856, 1, 3, null, 'Bessere Daten und Planung lenken Mittel gezielter, beseitigen den Rückstand aber nicht ohne zusätzliches Geld. Rasch und günstig umsetzbar; Wirkung kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=83', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9899, 37, 11, 'MV', 'Sportfördergesetz novellieren: Bürokratie abbauen, Antragsverfahren vollständig digitalisieren, Förderung des Landessportbundes dynamisieren', '{3703}', 9861, 2, 2, null, 'Verlässliche, mit den Kosten steigende Pauschalen setzen an der finanziellen Lage der Vereine an und erleichtern bezahlbare Beiträge. Dagegen: dauerhafte Haushaltsbelastung; Wirkung auf Beiträge kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=83', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9900, 37, 11, 'MV', 'Förderprogramm „Ehrenamt im Sport“ einführen, das mit dem Landessportbund Weiterbildungsmöglichkeiten für Ehrenamtliche finanziell absichert', '{3703}', 9870, 1, 3, null, 'Stärkt Qualifikation und Bindung von Ehrenamtlichen, entlastet die Vereinsfinanzen aber nur wenig. Rasch umsetzbar, Wirkung kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=99', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9901, 37, 11, 'MV', 'Landesprogramm zur Zusammenarbeit von Schulen und Sportvereinen, vor allem zur Einbindung der Vereine in den Ganztag', '{3703}', 9875, 1, 2, null, 'Kann Vereinen Nachwuchs und Einnahmen aus Ganztagsangeboten bringen, berührt ihre Finanzlage aber nur am Rand. Hängt von Übungsleitungen am Nachmittag ab; Wirkung kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=84', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9902, 37, 11, 'MV', 'GEMA-Gebühren für ehrenamtliche, eintrittsfreie Veranstaltungen gemeinnütziger Vereine per Landesprogramm übernehmen', '{3703}', 9874, 1, 3, null, 'Entlastet Vereine bei Veranstaltungskosten, für Sportvereine meist ein kleiner Posten; die finanzielle Lage verbessert sich nur am Rand. Mit überschaubarem Geld rasch umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=99', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9903, 37, 11, 'ST', 'Sportstättenförderung des Landes für Kommunen und Vereine fortsetzen', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=71', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9904, 37, 11, 'ST', 'Sportentwicklungsplanung und interkommunale Zusammenarbeit im Sport strukturell fördern', '{3701}', 9856, 1, 3, null, 'Bessere Daten und Planung lenken Mittel gezielter, beseitigen den Rückstand aber nicht ohne zusätzliches Geld. Rasch und günstig umsetzbar; Wirkung kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=71', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9905, 37, 11, 'ST', 'Neues Förderprogramm zur Entlastung der Vereine für Trainerinnen, Trainer und Übungsleiter auflegen', '{3703}', 9869, 2, 2, null, 'Setzt am Mangel an Übungsleitungen an, dem zweitgrößten Existenzproblem der Vereine, und entlastet deren Kasse. Dagegen: Studien zeigen, dass Bezahlung unbezahltes Engagement verdrängen kann; dauerhafte Finanzierung nötig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=71', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9906, 37, 11, 'ST', 'Landesprogramm „Ehrenamt“ als zentrale Förderlinie, u. a. für Sport: Projekte, Ausbildung, Nachwuchsgewinnung, Ausfallhilfen', '{3703}', 9865, 2, 2, null, 'Zusätzliche Mittel für Projekte, Nachwuchs und Strukturen setzen an der Lage der Vereine an. Dagegen: Wirkung hängt von Umfang und Antragsaufwand ab; kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=70', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9907, 37, 11, 'ST', 'Förderanträge und Verwendungsnachweise vereinfachen, digitale Antragsverfahren ausbauen, Förderverfahren vereinheitlichen', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=70', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9908, 37, 11, 'ST', 'Ehrenamts-Check bei neuen Gesetzen und Einsatz für einfacheres Vereins-, Gemeinnützigkeits- und Steuerrecht', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=70', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9909, 37, 11, 'ST', 'Auf Bundesebene für höhere Übungsleiter- und Ehrenamtspauschale eintreten', '{3703}', 9872, 1, 1, null, 'Wirkt wie die Erhöhung im Bund, entlastet aber nicht die Vereinskasse; Steuerrecht ist Bundessache, das Land kann nur über den Bundesrat drängen. Ob Geldanreize Engagement fördern, ist umstritten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=71', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9910, 37, 11, 'ST', 'GEMA-Ländervertrag anstreben, der ehrenamtlichen Vereinen bis zu vier lizenzkostenfreie Musiknutzungen pro Jahr ermöglicht', '{3703}', 9874, 1, 3, null, 'Entlastet Vereine bei Veranstaltungskosten, für Sportvereine meist ein kleiner Posten; die finanzielle Lage verbessert sich nur am Rand. Mit überschaubarem Geld rasch umsetzbar.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=37', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9911, 37, 12, null, 'Bund unterstützt Länder, Kommunen und Vereine bei der Sanierung von Sportstätten', '{3701}', 9876, 2, 3, null, 'Setzt direkt am Investitionsrückstand an; der Bund finanziert bereits ein Sanierungsprogramm (2025/26 rund 916 Mio. €). Dagegen: Mittel gemessen am Rückstand klein, Kofinanzierung und Planungskapazität der Kommunen begrenzen den Abruf.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=52', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9912, 37, 12, 'BE', 'Neubau, Sanierung, Barrierefreiheit und inklusive Sportstätten weiter vorantreiben', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9913, 37, 12, 'BE', 'Typenbauprogramm für Sportfunktionsgebäude und zentrale Planungs- und Baueinheit, die Bezirke entlastet und Bau und Sanierung beschleunigt', '{3701}', 9857, 1, 2, null, 'Kann Planung und Bau beschleunigen und verbilligen, wo Verwaltungskapazität der Engpass ist. Ohne zusätzliche Mittel bleibt der Rückstand; Aufbau einer zentralen Einheit dauert, Wirkung kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9914, 37, 12, 'BE', 'In landeseigene Schwimmbäder investieren, Typenschwimmhallen bauen und Bestandsbäder klimagerecht sanieren', '{3701}', 9854, 2, 2, null, 'Setzt am besonders hohen Rückstand bei Bädern an und kann Schließungen verhindern. Dagegen: sehr hohe Bau- und Betriebskosten, lange Bauzeiten; die Wirkung auf die Teilnahme hängt von Lage und Erreichbarkeit ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9915, 37, 12, 'BE', 'Unbürokratische Instandhaltungsbudgets für Vereine, ohne komplizierte Antragsverfahren selbst verwendbar', '{3701,3703}', 9860, 2, 2, null, 'Geld fließt direkt an Vereine für den Zustand ihrer Anlagen, wo der Problemdruck gestiegen ist; einfache Budgets erleichtern den Abruf. Dagegen: Umfang unbestimmt, Wirkung kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=55', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9916, 37, 12, 'BE', 'Sportstätten den Vereinen weiterhin gebührenfrei überlassen', '{3702}', null, 1, 3, null, 'Die weiterhin gebührenfreie Überlassung hält Nutzungskosten der Vereine niedrig, ändert am bestehenden Zustand aber nichts; die Kosten tragen weiter die Kommunen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=55', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9917, 37, 12, 'BE', 'Vereinsinvestitionsprogramm entbürokratisieren und finanziell stärken', '{3703,3701}', 9860, 2, 2, null, 'Geld fließt direkt an Vereine für den Zustand ihrer Anlagen, wo der Problemdruck gestiegen ist; einfache Budgets erleichtern den Abruf. Dagegen: Umfang unbestimmt, Wirkung kaum untersucht.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9918, 37, 12, 'BE', 'Fördervereinbarung mit dem Landessportbund über 2029 hinaus fortführen', '{3703}', 9862, 1, 3, null, 'Sichert bestehende Strukturen und gibt Planungssicherheit, verbessert die finanzielle Lage der Vereine aber kaum, solange die Mittel nicht steigen. Leicht umsetzbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9919, 37, 12, 'BE', 'Trainerinnen und Trainer weiter qualifizieren und ihre Einkommenssituation verbessern', '{3703}', 9869, 2, 2, null, 'Setzt am Mangel an Übungsleitungen an, dem zweitgrößten Existenzproblem der Vereine, und entlastet deren Kasse. Dagegen: Studien zeigen, dass Bezahlung unbezahltes Engagement verdrängen kann; dauerhafte Finanzierung nötig.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=56', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9920, 37, 12, 'MV', 'Sportstätten weiter über die bestehenden Programme fördern und zusätzliche Investitionsmittel des MV-Plans 2035 gezielt für ein Sportanlagenprogramm einsetzen', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=40', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9921, 37, 12, 'MV', 'Vereinen, Karneval und Kapellen die GEMA-Gebühren für bis zu drei öffentliche Veranstaltungen im Jahr erstatten', '{3703}', 9874, 1, 3, null, 'Entlastet Vereine bei Veranstaltungskosten, für Sportvereine meist ein kleiner Posten; die finanzielle Lage verbessert sich nur am Rand. Mit überschaubarem Geld rasch umsetzbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=5', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9922, 37, 12, 'ST', 'Pauschalen für Sportvereine verdoppeln, an die Kostenentwicklung koppeln und im Sportfördergesetz festschreiben', '{3703}', 9861, 2, 2, null, 'Verlässliche, mit den Kosten steigende Pauschalen setzen an der finanziellen Lage der Vereine an und erleichtern bezahlbare Beiträge. Dagegen: dauerhafte Haushaltsbelastung; Wirkung auf Beiträge kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9923, 37, 12, 'ST', 'Sportvereine bei der Digitalisierung ihrer Arbeit unterstützen', '{3703}', 9868, 1, 3, null, 'Kann Verwaltungsarbeit erleichtern und Ehrenamtliche entlasten, berührt die finanzielle Lage aber nur am Rand. Leicht umsetzbar, Wirkung kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9924, 37, 12, 'ST', 'Pauschalförderung für Kreis- und Stadtsportbünde sowie Landesfachverbände erhöhen und dynamisieren, Landessportbund auskömmlich finanzieren', '{3703}', 9861, 2, 2, null, 'Verlässliche, mit den Kosten steigende Pauschalen setzen an der finanziellen Lage der Vereine an und erleichtern bezahlbare Beiträge. Dagegen: dauerhafte Haushaltsbelastung; Wirkung auf Beiträge kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9925, 37, 12, 'ST', 'Landesinvestitionsprogramm für Schwimmhallen und Schwimmbäder auflegen', '{3701}', 9854, 2, 2, null, 'Setzt am besonders hohen Rückstand bei Bädern an und kann Schließungen verhindern. Dagegen: sehr hohe Bau- und Betriebskosten, lange Bauzeiten; die Wirkung auf die Teilnahme hängt von Lage und Erreichbarkeit ab.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9926, 37, 12, 'ST', 'Sportstätten erhalten und modernisieren; Kommunen bei Investitionen in Neubau, Barrierefreiheit, Energieeffizienz und Digitalisierung unterstützen', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=40', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9927, 37, 12, 'ST', 'Bürokratische Hürden für ehrenamtlich getragene Vereine und Initiativen gezielt abbauen (allgemein, nicht nur Sport)', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9928, 37, 13, null, 'Das Bundesprogramm zur Sanierung von Sportstätten und Schwimmbädern ausbauen, mit Blick auf ökologische Nachhaltigkeit und Inklusion.', '{3701}', 9876, 2, 3, null, 'Setzt direkt am Investitionsrückstand an; der Bund finanziert bereits ein Sanierungsprogramm (2025/26 rund 916 Mio. €). Dagegen: Mittel gemessen am Rückstand klein, Kofinanzierung und Planungskapazität der Kommunen begrenzen den Abruf.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=112', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9929, 37, 13, null, 'Kommunen besser finanzieren und über einen Deutschlandfonds Investitionen in kommunale Infrastruktur (u. a. Schwimmbäder, Sportplätze) ermöglichen.', '{3701}', 9877, 1, 2, null, 'Mehr Geld für Kommunen kann auch Sportstätten zugutekommen, ist aber nicht zweckgebunden; Sportanlagen konkurrieren mit vielen anderen Bedarfen. Finanzierung und Ausgestaltung offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=108', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9930, 37, 13, null, 'Aufwandsentschädigungen für Ehrenämter einheitlich pauschal steuerfrei stellen.', '{3703}', 9871, 1, 3, null, 'Steuerfreie Pauschalen entlasten Ehrenamtliche, nicht die Vereinskasse, die Zahlungen aufbringen muss; 2026 bereits erhöht. Ob Geldanreize mehr Engagement bringen, ist umstritten (Verdrängungseffekte).', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=111', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9931, 37, 13, null, 'Gemeinnützige zivilgesellschaftliche Organisationen von überflüssiger Bürokratie entlasten.', '{3703}', 9867, 1, 3, null, 'Der Bund regelt Vereins-, Haftungs- und Gemeinnützigkeitsrecht und kann Ehrenamtliche entlasten. Dagegen: Datenschutz ist EU-rechtlich vorgegeben; Wirkung auf Engagement und Vereinsfinanzen kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=112', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9932, 37, 13, 'BE', 'Sportstätten inklusiv, multifunktional und ökologisch sanieren und wo nötig neu bauen', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=36', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9933, 37, 13, 'BE', 'Mit Sportstätten-Entwicklungsplanung und Unterstützung der Bezirke ein Netz barrierefreier, klimaneutraler Sportstätten schaffen, mindestens drei inklusive je Bezirk', '{3701}', 9853, 1, 2, null, 'Verbessert Zugang und Teilhabe, berührt den allgemeinen Sanierungsrückstand aber nur, soweit dabei saniert wird. Umbau und Neubau brauchen Mittel und mehrere Jahre; Wirkung auf die Vereinsfinanzen kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=39', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9934, 37, 13, 'BE', 'Schwimmbadoffensive: Bäder schnell neu bauen und wiedereröffnen, gezielt in Bezirken mit fehlender Infrastruktur investieren', '{3701}', 9854, 2, 2, null, 'Setzt am besonders hohen Rückstand bei Bädern an und kann Schließungen verhindern. Dagegen: sehr hohe Bau- und Betriebskosten, lange Bauzeiten; die Wirkung auf die Teilnahme hängt von Lage und Erreichbarkeit ab.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=40', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9935, 37, 13, 'BE', 'Bäder energetisch sanieren, um Strom- und Wärmeversorgung zu optimieren und Betriebskosten zu senken, etwa mit Wärmerückgewinnung', '{3702,3701}', 9855, 2, 2, null, 'Energetische Sanierung senkt Energie- und Betriebskosten nachweislich deutlich (Pilotbad: über 50 % weniger Heizenergie) und baut Sanierungsbedarf ab. Dagegen: hohe Investitionen, lange Bauzeiten und Schließung während der Arbeiten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=40', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'belegt', '2026-10-08', false, true, 'blind'),
  (9936, 37, 13, 'BE', 'Sporthallen und -plätze vorrangig für den Vereinssport; Nutzungsvorschriften ändern, damit Vereine bessere Chancen auf Trainingszeiten erhalten', '{3701}', 9858, 1, 3, null, 'Schafft mehr Trainingszeiten ohne Neubau und lindert so Folgen knapper Anlagen, setzt am Investitionsrückstand selbst aber nicht an. Günstig umsetzbar; Wirkung kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=36', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9937, 37, 13, 'BE', 'Vergütung von Übungsleitern im Kinder-, Jugend- und Inklusionssport perspektivisch auf 20 bis 25 Euro pro Stunde anheben', '{3703}', 9869, 2, 2, null, 'Setzt am Mangel an Übungsleitungen an, dem zweitgrößten Existenzproblem der Vereine, und entlastet deren Kasse. Dagegen: Studien zeigen, dass Bezahlung unbezahltes Engagement verdrängen kann; dauerhafte Finanzierung nötig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=37', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9938, 37, 13, 'BE', 'Förderung hauptamtlicher Verwaltungskräfte in Vereinen erleichtern: nötige Mitgliedszahlen in der Fördervereinbarung mit dem Landessportbund deutlich senken', '{3703}', 9863, 2, 2, null, 'Setzt am größten Existenzproblem an, der Last auf Ehrenamtlichen. Studien: Vereine mit Hauptamt haben weniger Probleme bei Mitgliedern, aber mehr bei den Finanzen; dauerhafte Finanzierung nötig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=37', null, 'gemischt', '2026-10-08', false, true, 'blind'),
  (9939, 37, 13, 'MV', 'Ausbau umweltschonender Infrastruktur wie Schwimmhallen für ganzjährige Angebote für Gäste und Einheimische', '{3701}', 9854, 2, 2, null, 'Setzt am besonders hohen Rückstand bei Bädern an und kann Schließungen verhindern. Dagegen: sehr hohe Bau- und Betriebskosten, lange Bauzeiten; die Wirkung auf die Teilnahme hängt von Lage und Erreichbarkeit ab.', 'https://gruene-mv.de/?wpdmdl=33772#page=27', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9940, 37, 13, 'ST', 'Sanierung von Sportstätten und Schwimmbädern mit Fokus auf ökologische Nachhaltigkeit und Inklusion', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=72', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9941, 37, 13, 'ST', 'Kommunen und Sportvereine bei Klimaanpassungs- und Klimaschutzmaßnahmen in Sportstätten unterstützen', '{3701}', 9855, 2, 2, null, 'Energetische Sanierung senkt Energie- und Betriebskosten nachweislich deutlich (Pilotbad: über 50 % weniger Heizenergie) und baut Sanierungsbedarf ab. Dagegen: hohe Investitionen, lange Bauzeiten und Schließung während der Arbeiten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=72', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'belegt', '2026-10-08', false, true, 'blind'),
  (9942, 37, 13, 'ST', 'Sportvereine gezielt bei Energiekosten und Sanierungen unterstützen', '{3702,3701}', null, 2, 2, null, 'Zuschüsse zu Energiekosten und Sanierungen setzen an Betriebskosten und Anlagenzustand an. Dagegen: Umfang offen, Energiekostenhilfen lindern ohne Sanierung nur Folgen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=72', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9943, 37, 13, 'ST', 'Vereine bei der Entschädigung ehrenamtlicher Übungsleitungen unterstützen, vor allem mit Angeboten für Kinder und Jugendliche', '{3703}', 9869, 2, 2, null, 'Setzt am Mangel an Übungsleitungen an, dem zweitgrößten Existenzproblem der Vereine, und entlastet deren Kasse. Dagegen: Studien zeigen, dass Bezahlung unbezahltes Engagement verdrängen kann; dauerhafte Finanzierung nötig.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=72', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9944, 37, 13, 'ST', 'Angemessene Ausstattung des Landessportbundes und der Kreissportbünde als hauptamtliche Stütze des Ehrenamts', '{3703}', 9862, 1, 3, null, 'Sichert bestehende Strukturen und gibt Planungssicherheit, verbessert die finanzielle Lage der Vereine aber kaum, solange die Mittel nicht steigen. Leicht umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=72', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9945, 37, 13, 'ST', 'Schulische Sportstätten stärker öffnen und bei Bedarf modernisieren und sanieren, mehr frei zugängliche Bewegungsflächen', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=73', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9946, 37, 13, 'ST', 'Ehrenamt im Sport durch Erhöhung der Ehrenamtspauschale und bessere Anerkennung stärken', '{3703}', 9872, 1, 1, null, 'Wirkt wie die Erhöhung im Bund, entlastet aber nicht die Vereinskasse; Steuerrecht ist Bundessache, das Land kann nur über den Bundesrat drängen. Ob Geldanreize Engagement fördern, ist umstritten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=73', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9947, 37, 14, null, 'Vereine bei Haftungsrisiken und Bürokratie entlasten, u. a. weniger Dokumentations- und Aufbewahrungspflichten und ein zentraler Vereinslotse', '{3703}', 9867, 1, 3, null, 'Der Bund regelt Vereins-, Haftungs- und Gemeinnützigkeitsrecht und kann Ehrenamtliche entlasten. Dagegen: Datenschutz ist EU-rechtlich vorgegeben; Wirkung auf Engagement und Vereinsfinanzen kaum untersucht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9948, 37, 14, null, 'Übungsleiter- und Ehrenamtspauschalen sowie relevante Einnahmegrenzen anpassen', '{3703}', 9871, 1, 3, null, 'Steuerfreie Pauschalen entlasten Ehrenamtliche, nicht die Vereinskasse, die Zahlungen aufbringen muss; 2026 bereits erhöht. Ob Geldanreize mehr Engagement bringen, ist umstritten (Verdrängungseffekte).', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=32', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9949, 37, 14, 'BE', 'Instandhaltung von Sportstätten neu regeln, damit Nutzende Baumaßnahmen eigenverantwortlich und mit finanzieller Planungssicherheit umsetzen; bei Sanierung Fokus auf Barrierefreiheit', '{3701}', 9860, 2, 2, null, 'Geld fließt direkt an Vereine für den Zustand ihrer Anlagen, wo der Problemdruck gestiegen ist; einfache Budgets erleichtern den Abruf. Dagegen: Umfang unbestimmt, Wirkung kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=83', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9950, 37, 14, 'BE', 'Kapazitäten der Sportanlagen an das Bevölkerungswachstum anpassen, etwa mit Bewegungsflächen und Open-Workout-Anlagen in Parks', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=83', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9951, 37, 14, 'BE', 'Vorhandene Sportanlagen besser nutzen: Onlineportal für die Nutzung von Sportanlagen, Schulhöfe und Sportanlagen auch außerhalb der Schulzeiten öffnen', '{3701}', 9858, 1, 3, null, 'Schafft mehr Trainingszeiten ohne Neubau und lindert so Folgen knapper Anlagen, setzt am Investitionsrückstand selbst aber nicht an. Günstig umsetzbar; Wirkung kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=83', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9952, 37, 14, 'BE', 'Breitensport über die Förderung von Vereinen unterstützen', '{3703}', 9864, 1, 3, null, 'Berührt die finanzielle Lage der Vereine, nennt aber weder Instrument noch Umfang; eine spürbare Verbesserung ist so nicht absehbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=83', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9953, 37, 14, 'BE', 'Verlässliche und langfristige Finanzierung des Landessportbunds garantieren', '{3703}', 9862, 1, 3, null, 'Sichert bestehende Strukturen und gibt Planungssicherheit, verbessert die finanzielle Lage der Vereine aber kaum, solange die Mittel nicht steigen. Leicht umsetzbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=84', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9954, 37, 14, 'MV', 'Gemeinsam mit den Kommunen ein langfristiges Programm zur Sanierung und Modernisierung von Sportstätten mit verlässlicher, planbarer Förderung auflegen', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=124', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9955, 37, 14, 'MV', 'Einen regelmäßig fortgeschriebenen Zustandsbericht der Sportstätten im Land für einen sinnvollen Mitteleinsatz einfordern', '{3701}', 9856, 1, 3, null, 'Bessere Daten und Planung lenken Mittel gezielter, beseitigen den Rückstand aber nicht ohne zusätzliches Geld. Rasch und günstig umsetzbar; Wirkung kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=124', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9956, 37, 14, 'MV', 'Barrierefreie Planung und Anpassung von Sportstätten unterstützen', '{3701}', 9853, 1, 2, null, 'Verbessert Zugang und Teilhabe, berührt den allgemeinen Sanierungsrückstand aber nur, soweit dabei saniert wird. Umbau und Neubau brauchen Mittel und mehrere Jahre; Wirkung auf die Vereinsfinanzen kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=124', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9957, 37, 14, 'MV', 'Vereine sollen Schulen, Sporthallen und kommunale Einrichtungen außerhalb der regulären Nutzungszeiten unbürokratisch und möglichst kostenfrei nutzen können', '{3702}', 9859, 2, 2, null, 'Senkt die Nutzungskosten der Vereine und damit den Druck auf Beiträge. Dagegen: Die Kosten verlagern sich auf Kommunen, deren Sportbetriebe schon Verluste ausgleichen; ohne Ausgleich durch das Land kaum tragfähig. Wenig untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9958, 37, 14, 'MV', 'Alle Landesförderprogramme für Ehrenamt und Vereine zentral bündeln, digital, mit einfachen Antragswegen, Pauschalen und verständlichen Nachweisen', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9959, 37, 14, 'MV', 'Für eine Erhöhung der steuerlichen Freibeträge für Übungsleiter- und Ehrenamtspauschalen eintreten', '{3703}', 9872, 1, 1, null, 'Wirkt wie die Erhöhung im Bund, entlastet aber nicht die Vereinskasse; Steuerrecht ist Bundessache, das Land kann nur über den Bundesrat drängen. Ob Geldanreize Engagement fördern, ist umstritten.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9960, 37, 14, 'MV', 'Vereine bei der Umsetzung des Datenschutzes entlasten: Muster, zentrale Beratung und Bagatellregelungen bei geringem Risiko', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9961, 37, 14, 'MV', 'Gezielte Programme zur Stärkung ehrenamtlicher Strukturen im ländlichen Raum entwickeln, wo Bevölkerungsrückgang Vereine gefährdet', '{3703}', 9865, 2, 2, null, 'Zusätzliche Mittel für Projekte, Nachwuchs und Strukturen setzen an der Lage der Vereine an. Dagegen: Wirkung hängt von Umfang und Antragsaufwand ab; kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9962, 37, 14, 'MV', 'Bürokratische Hindernisse im Sport abbauen, insbesondere bei Förderanträgen, Genehmigungen und Bauvorhaben', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=124', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9963, 37, 14, 'ST', 'Kontinuierliche Investitionen in Sportstätten, damit die Nutzung kommunaler Sportstätten für Vereine bezahlbar bleibt', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9964, 37, 14, 'ST', 'Planungs- und Förderverfahren für Sportstätten beschleunigen, digitalisieren und ehrenamtsfreundlich gestalten', '{3701}', 9857, 1, 2, null, 'Kann Planung und Bau beschleunigen und verbilligen, wo Verwaltungskapazität der Engpass ist. Ohne zusätzliche Mittel bleibt der Rückstand; Aufbau einer zentralen Einheit dauert, Wirkung kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9965, 37, 14, 'ST', 'Pauschalförderung für Vereine und Mitgliedsorganisationen dauerhaft erhöhen und dynamisieren', '{3703}', 9861, 2, 2, null, 'Verlässliche, mit den Kosten steigende Pauschalen setzen an der finanziellen Lage der Vereine an und erleichtern bezahlbare Beiträge. Dagegen: dauerhafte Haushaltsbelastung; Wirkung auf Beiträge kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9966, 37, 14, 'ST', 'Vereine mit eigenen Sportanlagen bei der Förderung den Nutzern kommunaler Sportstätten gleichstellen, Sportfördergesetz anpassen', '{3703,3702}', null, 1, 2, null, 'Gleichstellung bei der Förderung entlastet Vereine, die eigene Anlagen tragen und betreiben. Umfang offen, Gesetzesänderung nötig; Wirkung kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9967, 37, 14, 'ST', 'Ehrenamt im Sport stärken durch Anerkennungsinstrumente, mehr Sichtbarkeit und bessere Vereinbarkeit mit Schule, Studium und Beruf', '{3703}', 9873, 1, 2, null, 'Würdigt Ehrenamtliche und kann Bindung stärken; Evaluationen zeigen Zufriedenheit, aber keinen belegten Effekt auf die Gewinnung neuer Engagierter. Vergünstigungen wie freier Nahverkehr kosten Geld.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9968, 37, 14, 'ST', 'Auflagen, Dokumentationspflichten und Förderbürokratie für Sportvereine abbauen', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=51', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9969, 37, 14, 'ST', 'Trainer- und Übungsleiterstrukturen dauerhaft sichern, besonders im Nachwuchs- und Leistungssport', '{3703}', 9869, 2, 2, null, 'Setzt am Mangel an Übungsleitungen an, dem zweitgrößten Existenzproblem der Vereine, und entlastet deren Kasse. Dagegen: Studien zeigen, dass Bezahlung unbezahltes Engagement verdrängen kann; dauerhafte Finanzierung nötig.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9970, 37, 14, 'ST', 'Sport in Kita und Schule stärken und Kooperationen mit Sportvereinen ausbauen', '{3703}', 9875, 1, 2, null, 'Kann Vereinen Nachwuchs und Einnahmen aus Ganztagsangeboten bringen, berührt ihre Finanzlage aber nur am Rand. Hängt von Übungsleitungen am Nachmittag ab; Wirkung kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=52', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9971, 37, 15, 'BE', 'Sanierungsstau bei Sportflächen mit massiven Investitionen und einem Sofortprogramm beheben', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=65', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9972, 37, 15, 'BE', 'Bei Neubauvorhaben den Bedarf an zusätzlichen Sportflächen berücksichtigen', '{3701}', 9856, 1, 3, null, 'Bessere Daten und Planung lenken Mittel gezielter, beseitigen den Rückstand aber nicht ohne zusätzliches Geld. Rasch und günstig umsetzbar; Wirkung kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=66', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9973, 37, 15, 'MV', 'Sicherstellen, dass Kommunen und Vereine Fördermittel für die Sanierung von Sportstätten und Schwimmhallen vollständig und unbürokratisch abrufen können', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=72', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9974, 37, 15, 'MV', 'Aufwandsentschädigungen ehrenamtlicher Trainer, Übungsleiter und Schiedsrichter regelmäßig an Lohn- und Preisentwicklung anpassen', '{3703}', 9869, 2, 2, null, 'Setzt am Mangel an Übungsleitungen an, dem zweitgrößten Existenzproblem der Vereine, und entlastet deren Kasse. Dagegen: Studien zeigen, dass Bezahlung unbezahltes Engagement verdrängen kann; dauerhafte Finanzierung nötig.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=66', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9975, 37, 15, 'MV', 'Bürokratische Hürden für Vereine bei Förderanträgen, Versicherungs- und Nachweispflichten systematisch abbauen', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=66', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9976, 37, 15, 'MV', 'Breitensport als Gesundheitsvorsorge politisch und finanziell aufwerten', '{3703}', 9864, 1, 3, null, 'Berührt die finanzielle Lage der Vereine, nennt aber weder Instrument noch Umfang; eine spürbare Verbesserung ist so nicht absehbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=63', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9977, 37, 15, 'MV', 'Ehrenamtskarte überarbeiten und mit Vorteilen wie Nahverkehrsvergünstigungen, Eintrittsermäßigungen und steuerlichen Erleichterungen ausstatten', '{3703}', 9873, 1, 2, null, 'Würdigt Ehrenamtliche und kann Bindung stärken; Evaluationen zeigen Zufriedenheit, aber keinen belegten Effekt auf die Gewinnung neuer Engagierter. Vergünstigungen wie freier Nahverkehr kosten Geld.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=66', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9978, 37, 15, 'ST', 'Vereine für Sport (sowie Feuerwehr, Gesang, Brauchtum) im ländlichen Raum finanziell entlasten', '{3703}', 9864, 1, 3, null, 'Berührt die finanzielle Lage der Vereine, nennt aber weder Instrument noch Umfang; eine spürbare Verbesserung ist so nicht absehbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=193', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9979, 37, 16, null, 'Sanierung von Turnhallen und Sportplätzen sowie Bau moderner, barrierefreier Sportstätten und Schwimmbäder; Bund beteiligt sich 15 Jahre mit je einer Milliarde Euro jährlich', '{3701}', 9876, 2, 3, null, 'Setzt direkt am Investitionsrückstand an; der Bund finanziert bereits ein Sanierungsprogramm (2025/26 rund 916 Mio. €). Dagegen: Mittel gemessen am Rückstand klein, Kofinanzierung und Planungskapazität der Kommunen begrenzen den Abruf.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=56', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9980, 37, 16, null, 'Schwimmbäder und Sportstätten als Teil einer Infrastrukturgarantie der Daseinsvorsorge; Kommunen in Finanzkrisen erhalten Mittel aus einem Bundesfonds für eine Mindestausstattung', '{3702}', null, 1, 2, null, 'Ein Bundesfonds für Kommunen in Finanznot kann den Betrieb von Bädern und Sportstätten sichern, ist aber nicht zweckgebunden und nur Soforthilfe; Ausgestaltung offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9981, 37, 16, 'BE', 'Jahrzehnt der Investitionen in den Breitensport mit zentraler Baudienststelle für den Sportstättenbau', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=316', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9982, 37, 16, 'BE', 'Etat für Sportanlagen an Schulstandorten erhöhen und schnelle Sanierung der Schulsporthallen priorisieren', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=316', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9983, 37, 16, 'BE', 'Sanierung bezirklicher Sportanlagen im Sportanlagensanierungsprogramm beschleunigen und dessen Etat erhöhen', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=316', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9984, 37, 16, 'BE', 'Bezirke finanziell bei der Umsetzung ihrer Sportentwicklungspläne (neue Sportstätten) unterstützen', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=316', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9985, 37, 16, 'BE', 'Mindestens eine vollinklusive Sportanlage je Bezirk, Bau inklusiver Typensporthallen forcieren', '{3701}', 9853, 1, 2, null, 'Verbessert Zugang und Teilhabe, berührt den allgemeinen Sanierungsrückstand aber nur, soweit dabei saniert wird. Umbau und Neubau brauchen Mittel und mehrere Jahre; Wirkung auf die Vereinsfinanzen kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=315', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9986, 37, 16, 'BE', 'Sanierungsbedürftige, von Ausfall bedrohte Bäder vorrangig finanziell absichern', '{3701}', 9854, 2, 2, null, 'Setzt am besonders hohen Rückstand bei Bädern an und kann Schließungen verhindern. Dagegen: sehr hohe Bau- und Betriebskosten, lange Bauzeiten; die Wirkung auf die Teilnahme hängt von Lage und Erreichbarkeit ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=317', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9987, 37, 16, 'BE', 'Mittel des Bädervertrags verlässlich auszahlen und wegen gestiegener Bau- und Energiekosten dynamisieren', '{3702,3701}', 9854, 2, 2, null, 'Setzt am besonders hohen Rückstand bei Bädern an und kann Schließungen verhindern. Dagegen: sehr hohe Bau- und Betriebskosten, lange Bauzeiten; die Wirkung auf die Teilnahme hängt von Lage und Erreichbarkeit ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=317', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9988, 37, 16, 'BE', 'Sanierungsstau im Sportforum Hohenschönhausen und im Olympiapark abbauen', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=320', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9989, 37, 16, 'BE', 'Investitionsprogramm zur energetischen Sanierung der Kälteanlagen von Eissporthallen', '{3701}', 9855, 2, 2, null, 'Energetische Sanierung senkt Energie- und Betriebskosten nachweislich deutlich (Pilotbad: über 50 % weniger Heizenergie) und baut Sanierungsbedarf ab. Dagegen: hohe Investitionen, lange Bauzeiten und Schließung während der Arbeiten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=320', 'https://www.energiezukunft.eu/bauen/bauzukunft/energieeffizient-im-spa', 'belegt', '2026-10-08', false, true, 'blind'),
  (9990, 37, 16, 'BE', 'Sonderprogramm zur Sanierung bestehender öffentlicher Kiezsportflächen (Bolz- und Basketballplätze)', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=321', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9991, 37, 16, 'BE', 'Dem Sport im Sinne der Mehrfachnutzung weitgehenden Zugang zu Schulen ermöglichen', '{3701}', 9858, 1, 3, null, 'Schafft mehr Trainingszeiten ohne Neubau und lindert so Folgen knapper Anlagen, setzt am Investitionsrückstand selbst aber nicht an. Günstig umsetzbar; Wirkung kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9992, 37, 16, 'BE', 'Ungenutzte Sportorte reaktivieren und in Eigenverantwortung der Vereine geben, saisonale Sportstätten ganzjährig nutzen', '{3702}', null, 1, 2, null, 'Reaktivierte Orte in Vereinsverantwortung und ganzjährige Nutzung können Betriebskosten der Kommunen senken und Kapazität schaffen. Dagegen: Vereine übernehmen Lasten; Wirkung kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=317', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9993, 37, 16, 'BE', 'Übungsleiterpauschale spürbar anheben, um das Ehrenamt im Sport zu stützen', '{3703}', 9872, 1, 1, null, 'Wirkt wie die Erhöhung im Bund, entlastet aber nicht die Vereinskasse; Steuerrecht ist Bundessache, das Land kann nur über den Bundesrat drängen. Ob Geldanreize Engagement fördern, ist umstritten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9994, 37, 16, 'BE', 'Ehrenamt im Sport durch Digitalisierung von Bürokratie entlasten', '{3703}', 9868, 1, 3, null, 'Kann Verwaltungsarbeit erleichtern und Ehrenamtliche entlasten, berührt die finanzielle Lage aber nur am Rand. Leicht umsetzbar, Wirkung kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9995, 37, 16, 'BE', 'Fördervereinbarung mit dem Landessportbund fortschreiben und anpassen, für Planungssicherheit der Vereine', '{3703}', 9862, 1, 3, null, 'Sichert bestehende Strukturen und gibt Planungssicherheit, verbessert die finanzielle Lage der Vereine aber kaum, solange die Mittel nicht steigen. Leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9996, 37, 16, 'BE', 'Vereinsinvestitionsprogramm finanziell aufstocken und entbürokratisieren', '{3703,3701}', 9860, 2, 2, null, 'Geld fließt direkt an Vereine für den Zustand ihrer Anlagen, wo der Problemdruck gestiegen ist; einfache Budgets erleichtern den Abruf. Dagegen: Umfang unbestimmt, Wirkung kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9997, 37, 16, 'BE', 'Ergänzender Fonds mit dem Landessportbund für die Basis des Breitensports, v. a. Personal und Instandhaltung', '{3703,3701}', 9860, 2, 2, null, 'Geld fließt direkt an Vereine für den Zustand ihrer Anlagen, wo der Problemdruck gestiegen ist; einfache Budgets erleichtern den Abruf. Dagegen: Umfang unbestimmt, Wirkung kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=313', null, 'offen', '2026-10-08', false, true, 'blind'),
  (9998, 37, 16, 'MV', 'Sportanlagen im Land ausbauen und sanieren', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (9999, 37, 16, 'MV', 'Landesprogramme für Kinderbewegung, Sport in Schule und Verein sowie Schwimmen ausfinanzieren', '{3703}', 9875, 1, 2, null, 'Kann Vereinen Nachwuchs und Einnahmen aus Ganztagsangeboten bringen, berührt ihre Finanzlage aber nur am Rand. Hängt von Übungsleitungen am Nachmittag ab; Wirkung kaum untersucht.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10000, 37, 16, 'ST', 'Langfristige Investitionsprogramme, mit denen das Land Kommunen bei Sanierung und Modernisierung von Bädern, Turnhallen und Sportanlagen verlässlich unterstützt', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=67', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10001, 37, 16, 'ST', 'Förderung des Vereinssportstättenbaus so ausstatten, dass Sanierungen und Neubauten der Vereine umgesetzt werden; planbare, unbürokratische Programme auch für kleine Vereine', '{3701}', 9860, 2, 2, null, 'Geld fließt direkt an Vereine für den Zustand ihrer Anlagen, wo der Problemdruck gestiegen ist; einfache Budgets erleichtern den Abruf. Dagegen: Umfang unbestimmt, Wirkung kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=67', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10002, 37, 16, 'ST', 'Vereinen ohne eigene Sportstätten Zugang zu Sportstätten ermöglichen; Nutzung muss finanzierbar sein', '{3702}', null, 1, 2, null, 'Bezahlbarer Zugang zu Sportstätten senkt Nutzungskosten der Vereine ohne eigene Anlagen; die Zusage nennt aber weder Instrument noch Finanzierung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=68', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10003, 37, 16, 'ST', 'Förderung des Ehrenamts im Sport mit dem Landessportbund weiterentwickeln, u. a. landesweite Ehrenamtskarte und Sicherung der Freiwilligendienste', '{3703}', 9873, 1, 2, null, 'Würdigt Ehrenamtliche und kann Bindung stärken; Evaluationen zeigen Zufriedenheit, aber keinen belegten Effekt auf die Gewinnung neuer Engagierter. Vergünstigungen wie freier Nahverkehr kosten Geld.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=68', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10004, 37, 16, 'ST', 'Vereine gezielt bei Aus- und Fortbildung von Übungsleitern und Trainern sowie bei der Digitalisierung unterstützen', '{3703}', 9870, 1, 3, null, 'Stärkt Qualifikation und Bindung von Ehrenamtlichen, entlastet die Vereinsfinanzen aber nur wenig. Rasch umsetzbar, Wirkung kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=68', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10005, 37, 16, 'ST', 'Gesetz zur Stärkung des Ehrenamts mit Ehrenamtsfonds und Kommunalbudget für Strukturen des Engagements (allgemein, nicht nur Sport)', '{3703}', 9865, 2, 2, null, 'Zusätzliche Mittel für Projekte, Nachwuchs und Strukturen setzen an der Lage der Vereine an. Dagegen: Wirkung hängt von Umfang und Antragsaufwand ab; kaum untersucht.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=14', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10006, 37, 17, null, 'Investitionsprogramm für kinder- und familienfreundliche Infrastruktur in Kommunen mit Sanierungsstau, mit wohnortnahem Zugang u. a. zu Sportstätten.', '{3701}', 9877, 1, 2, null, 'Mehr Geld für Kommunen kann auch Sportstätten zugutekommen, ist aber nicht zweckgebunden; Sportanlagen konkurrieren mit vielen anderen Bedarfen. Finanzierung und Ausgestaltung offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10007, 37, 17, 'BE', 'Sanierungsoffensive für Sportstätten: Kürzungen stoppen, Sanierungsmittel verdoppeln, Vorrang für Instandhaltung, Umbau und barrierefreie Modernisierung', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10008, 37, 17, 'BE', 'Kein Abriss von Sportstätten ohne gleichwertigen Ersatz; bestehende Anlagen wie SEZ und Jahn-Sportpark erhalten und ertüchtigen', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10009, 37, 17, 'BE', 'Neue Sporthallen und Plätze dort bauen, wo sie dringend benötigt werden', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10010, 37, 17, 'BE', 'Kostenlose oder stark vergünstigte Nutzung kommunaler Sportanlagen für Vereine', '{3702}', 9859, 2, 2, null, 'Senkt die Nutzungskosten der Vereine und damit den Druck auf Beiträge. Dagegen: Die Kosten verlagern sich auf Kommunen, deren Sportbetriebe schon Verluste ausgleichen; ohne Ausgleich durch das Land kaum tragfähig. Wenig untersucht.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10011, 37, 17, 'BE', 'Gezielte Unterstützung für Trainer, Ehrenamtliche und Inklusionsprojekte im Breitensport', '{3703}', 9864, 1, 3, null, 'Berührt die finanzielle Lage der Vereine, nennt aber weder Instrument noch Umfang; eine spürbare Verbesserung ist so nicht absehbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10012, 37, 17, 'BE', 'Vollständige Sanierung aller Schulsportstätten', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=27', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10013, 37, 17, 'MV', 'Regelmäßige Sanierung und Modernisierung bestehender kommunaler Infrastruktur, ausdrücklich auch Sporthallen und Schwimmbäder', '{3701}', 9852, 1, 3, null, 'Setzt am Sanierungsbedarf an, aber ohne zusätzliche Mittel oder nur für einzelne Anlagen; der wachsende Rückstand wird so kaum kleiner. Dafür spricht, dass bestehende Förderung ohne Neuregelung weiterlaufen kann.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=76', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10014, 37, 17, 'MV', 'Unbürokratischer Soforthilfefonds für kleine Vereine, etwa 1.000 Euro pro Verein', '{3703}', null, 1, 3, null, 'Einmalige kleine Hilfe von etwa 1.000 Euro entlastet kleine Vereine kurzfristig, ändert ihre finanzielle Lage aber nicht dauerhaft. Rasch umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=78', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10015, 37, 17, 'MV', 'Jährlicher Anerkennungsbonus für Übungsleiter, Jugendbetreuer und Vorstandsmitglieder im Ehrenamt', '{3703}', 9869, 2, 2, null, 'Setzt am Mangel an Übungsleitungen an, dem zweitgrößten Existenzproblem der Vereine, und entlastet deren Kasse. Dagegen: Studien zeigen, dass Bezahlung unbezahltes Engagement verdrängen kann; dauerhafte Finanzierung nötig.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=78', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10016, 37, 17, 'MV', 'Landesweites digitales Vereinsportal zur Vereinfachung von Verwaltung, Förderung und Beratung der Vereine', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=77', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10017, 37, 17, 'ST', 'In Erhalt und Neubau von Sportstätten investieren, vorrangig Schulsportstätten und Bäder; Förderprogramme langfristig, einfach und auf Energieeffizienz und Mehrfachnutzung ausrichten', '{3701}', 9851, 2, 2, null, 'Setzt direkt am Investitionsrückstand an; zusätzliche, verlässliche Mittel bauen ihn ab. Dagegen: Planungs- und Baukapazitäten der Kommunen begrenzen das Tempo; dass bessere Anlagen die Teilnahme erhöhen, zeigen Studien vor allem für ländliche Räume.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=41', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10018, 37, 17, 'ST', 'Ehrenamt stärken: Freistellungsgesetz auf privates Ehrenamt ausweiten, Ehrenamtspauschalen erhöhen, Ehrenamt bei der Rente anrechnen', '{3703}', null, 1, 2, null, 'Freistellung für privates Ehrenamt kann das Land regeln; Pauschalen und Rentenanrechnung sind Bundesrecht. Ob solche Anreize mehr Engagement bringen, ist umstritten.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=42', 'https://ideas.repec.org/p/zur/iewwpx/007.html', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10019, 37, 17, 'ST', 'Verwaltungs- und Förderverfahren vereinfachen, um Vereine und Verbände zu entlasten', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=42', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10020, 37, 18, null, 'Mehr Bundesmittel für Sportvereine und ehrenamtliche Initiativen bereitstellen', '{3703}', null, 1, 2, null, 'Mehr Bundesmittel würden die Finanzlage der Vereine verbessern; Umfang und Weg sind offen, und Breitensport ist Ländersache, der Bund kann nur über Programme beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=130', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10021, 37, 18, null, 'Sportstätten barrierefrei gestalten und spezielle Förderprogramme für Menschen mit Behinderung einrichten', '{3701}', null, 1, 2, null, 'Barrierefreie Sportstätten verbessern Teilhabe, berühren den Sanierungsrückstand nur beim Umbau. Sportstätten sind Sache von Ländern und Kommunen; der Bund kann nur über Förderprogramme beitragen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=161', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10022, 37, 18, null, 'Nationale Kampagnen zur Gewinnung neuer Vereinsmitglieder, besonders Kinder, Jugendliche und sozial Benachteiligte', '{3703}', null, 1, 3, null, 'Kampagnen können Mitglieder und damit Beitragseinnahmen bringen, setzen an der finanziellen Lage der Vereine aber nur indirekt an; Wirkung solcher Kampagnen kaum belegt.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=161', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10023, 37, 18, 'BE', 'Bessere Nutzung der Sportstandorte: Schulhöfe, Sporthallen und Grünflächen auch nach Schulschluss, am Wochenende und in den Ferien öffnen', '{3701}', 9858, 1, 3, null, 'Schafft mehr Trainingszeiten ohne Neubau und lindert so Folgen knapper Anlagen, setzt am Investitionsrückstand selbst aber nicht an. Günstig umsetzbar; Wirkung kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=87', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10024, 37, 18, 'BE', 'Buchung von Hallen und Plätzen für Vereine über ein transparentes Online-System vereinfachen, freie Kapazitäten sichtbar machen', '{3701}', 9858, 1, 3, null, 'Schafft mehr Trainingszeiten ohne Neubau und lindert so Folgen knapper Anlagen, setzt am Investitionsrückstand selbst aber nicht an. Günstig umsetzbar; Wirkung kaum untersucht.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=87', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10025, 37, 18, 'BE', 'Zuschüsse für Ausrüstung oder Honorare an Vereine, die Zugewanderte und Geflüchtete aktiv einbinden', '{3703}', null, 1, 3, null, 'Zuschüsse für Ausrüstung und Honorare entlasten einen kleinen Teil der Vereine zweckgebunden; die finanzielle Lage der Vereine insgesamt berührt das nur am Rand.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=88', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10026, 37, 18, 'MV', 'Ehrenamtskarte so anpassen, dass ehrenamtlich Engagierte unter Federführung des Landes den ÖPNV kostenlos nutzen können', '{3703}', 9873, 1, 2, null, 'Würdigt Ehrenamtliche und kann Bindung stärken; Evaluationen zeigen Zufriedenheit, aber keinen belegten Effekt auf die Gewinnung neuer Engagierter. Vergünstigungen wie freier Nahverkehr kosten Geld.', 'https://voltdeutschland.org/storage/assets-mv/pdf/haltungzeigen_wahlprogramm_voltmv_ltw26.pdf#page=15', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10027, 37, 18, 'ST', 'Landesinvestitionsprogramm für Schwimmhallen und Schwimmbäder, das Sanierung, Neubau und Betrieb langfristig sichert', '{3701,3702}', 9854, 2, 2, null, 'Setzt am besonders hohen Rückstand bei Bädern an und kann Schließungen verhindern. Dagegen: sehr hohe Bau- und Betriebskosten, lange Bauzeiten; die Wirkung auf die Teilnahme hängt von Lage und Erreichbarkeit ab.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=29', 'https://www.alexandria.unisg.ch/id/eprint/237715', 'gemischt', '2026-10-08', false, true, 'blind'),
  (10028, 37, 18, 'ST', 'Gezielte Förderung von Vereinen mit hohem Jugendanteil durch Zuschüsse für Übungsleiter, Ausstattung und Infrastruktur', '{3703}', 9865, 2, 2, null, 'Zusätzliche Mittel für Projekte, Nachwuchs und Strukturen setzen an der Lage der Vereine an. Dagegen: Wirkung hängt von Umfang und Antragsaufwand ab; kaum untersucht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=27', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10029, 37, 18, 'ST', 'Einfachere Förderanträge und Bürokratieabbau für ehrenamtlich geführte Vereine', '{3703}', 9866, 1, 3, null, 'Entlastet Ehrenamtliche, für die Vorschriften ein häufig genanntes Problem sind. Dagegen: Viele Pflichten stammen aus Bundes- oder EU-Recht; ob Entlastung mehr Engagement bringt, ist kaum untersucht.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=27', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10030, 37, 18, 'ST', 'Landessportbund als zentrale Säule der Sportförderung weiterführen und auskömmlich finanzieren', '{3703}', 9862, 1, 3, null, 'Sichert bestehende Strukturen und gibt Planungssicherheit, verbessert die finanzielle Lage der Vereine aber kaum, solange die Mittel nicht steigen. Leicht umsetzbar.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=153', null, 'offen', '2026-10-08', false, true, 'blind'),
  (10031, 37, 18, 'ST', 'Land übernimmt GEMA-Gebühren für bis zu vier nicht-kommerzielle, eintrittsfreie Veranstaltungen pro Jahr je gemeinnützigem Verein', '{3703}', 9874, 1, 3, null, 'Entlastet Vereine bei Veranstaltungskosten, für Sportvereine meist ein kleiner Posten; die finanzielle Lage verbessert sich nur am Rand. Mit überschaubarem Geld rasch umsetzbar.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=154', null, 'offen', '2026-10-08', false, true, 'blind');

